  const node = document.querySelector('.str-item[data-si="' + idx + '"]');
  if (!node) return;
  node.classList.add("on");
  let tag = node.querySelector(".str-now");
  if (!tag) { tag = el('<div class="str-now"></div>'); node.appendChild(tag); }
