function sessionSheetHtml(sess, week) {
  const sc = "var(--eff-" + effortOf(sess) + ")";
  // ⚠️ THE TIME ON THE CARD MUST INCLUDE THE WARM-UP WE ACTUALLY PRESCRIBE. Generating longer,
  // more specific warm-ups without telling the clock made every number here wrong: measured, an
  // interval session said 50 minutes and really wanted 69, and race day said 115 against 139. The
  // paper lists this as a content assertion for exactly that reason — a warm-up you did not budget
  // for is one the runner skips.
  // ⚠️ The session's OWN estimatedDurationSeconds is left alone. It feeds the volume and intensity
  // models, and rewriting it here would reshape every plan in the app — the weeklyVolumeKm trap in
  // a new coat. This adjusts what is DISPLAYED, nothing else.
  const wu = warmupCardFor(sess);
  // ⚠️ THE TIME ON THE CHIP IS MEASURED ON THE SESSION START WILL ACTUALLY RUN. It used to be
  // rebuilt here from the warm-up's own totalMinutes, which is a second formula for the same
  // quantity — and two formulas drift: measured across 432 sessions, 57 chips disagreed with what
  // Start delivered, by up to 1.7 minutes in both directions, because the engine rounds a strides
  // block to whole minutes while the step is 75 s per stride. There is one answer now, and it comes
  // from the steps themselves.
  const live = wu ? withGeneratedWarmup(sess) : sess;
  const liveSec = (live.steps || []).reduce((a, st) => a + (st.durationSeconds || 0), 0);
  const ownWu = (sess.steps || []).filter((st) => st.kind === "warmup")
    .reduce((a, st) => a + (st.durationSeconds || 0), 0) / 60;
  const dur = liveSec ? Math.round(liveSec / 60) : Math.round(sess.estimatedDurationSeconds / 60);
  const extra = (wu && !wu.embedded && !wu.incomplete)
    ? Math.max(0, dur - Math.round(sess.estimatedDurationSeconds / 60)) : 0;
  const dist = sess.estimatedDistanceMeters ? (Math.round(sess.estimatedDistanceMeters / 100) / 10) + " km" : null;
  const chips = ['<span class="chip">' + dur + "′" + (dist ? " · " + dist : "") + "</span>"];
  // Same rule: quote the warm-up the runner is given, not the engine's rounded estimate of it.
  if (extra > 0) chips.push('<span class="chip">incl. ' + Math.round(((live.steps || [])
    .filter((st) => st.kind === "warmup")
    .reduce((a, st) => a + (st.durationSeconds || 0), 0)) / 60) + "′ warm-up</span>");
  if (sess.targetRpe) chips.push('<span class="chip rpe">RPE ' + sess.targetRpe.min + "–" + sess.targetRpe.max + "</span>");
  let body;
  if (sess.exercises && sess.exercises.length) {
    body = '<div class="ex-list">' + sess.exercises.map((e, ei) => exerciseBlock(sess.id, ei, e)).join("") + '</div>';
  } else {
    // ⚠️ ONE WARM-UP ON SCREEN. The generated card below is the authority now, so the session's own
    // one-line warm-up step is dropped from this list rather than printed above it saying a shorter
    // version of the same thing. The STEP itself is untouched — the live runtime, the watch and the
    // timings all still run from it; this only stops the brief saying it twice.
    const shown = warmupCardFor(sess) ? sess.steps.filter((st) => st.kind !== "warmup") : sess.steps;
    const rows = structureRows(shown).map((r) =>
      '<div class="sd-step"><div class="sd-dot" style="background:' + (r.muted ? "var(--ink-faint)" : sc) + '"></div><div><div class="sd-tag">' + r.tag + '</div><div class="sd-lab">' + r.lab + '</div>' + (r.chips ? '<div class="sd-meta">' + r.chips + '</div>' : "") + (r.rec ? '<div class="sd-rec">' + r.rec + '</div>' : "") + '</div></div>').join("");
    // The warm-up comes first because that is when it happens.
    body = warmupHtml(sess) + (rows ? '<div class="sd-steps">' + rows + '</div>' : "");
  }
  // Reschedule row — pick any day; a run already there swaps with this one.
  const cur = effDay(sess);
  const dayPicker = DAY_ORDER.map((dn, i) => '<button class="sd-day' + (i === cur ? " on" : "") + '" data-moveto="' + i + '"' + (i === cur ? " disabled" : "") + '>' + dn + '</button>').join("");
  const moveBlock = sess.type === "rest" ? "" :
    '<div class="sd-move"><div class="sd-move-h">Move to another day</div><div class="sd-days">' + dayPicker + '</div><div class="sd-move-n">Pick a day. If a run is already there, the two will swap.</div></div>';
  const startBtn = PRIMARY_TYPES[sess.type] ? '<button class="primary sd-start" id="sdStart">' + ICON.play + ' Start session</button>' : "";
  const addLink = '<button class="sd-addlink" id="sdAdd">\\uFF0B Add a different session ' + dayPhraseIso(isoAdd(weekByNo(week).startIso, effDay(sess)).toISOString().slice(0, 10)) + '</button>';
  return '<div class="sd-type" style="--sc:' + sc + '">' + (SESSION_LABEL[sess.type] || sess.type) + '</div>' +
    '<div class="sd-title">' + esc(sess.title) + '</div>' +
    '<div class="sd-chips">' + chips.join("") + '</div>' +
    startBtn +
    '<div class="sd-desc">' + esc(sess.description) + '</div>' +
    body +
    fuelHtml(sess) +
    moveBlock +
    addLink;
}
function ensureSheet() {
  if ($("sheetOv")) return;
  const node = el('<div class="sheet-ov" id="sheetOv"><div class="sheet"><button class="sheet-x" id="sheetClose" aria-label="Close">✕</button><div class="sheet-body" id="sheetBody"></div></div></div>');
  document.querySelector(".app").appendChild(node);
  $("sheetClose").onclick = closeSheet;
  $("sheetOv").onclick = (e) => { if (e.target === $("sheetOv")) closeSheet(); };
}
function wireSheet() {
  document.querySelectorAll("[data-moveto]").forEach((b) => b.onclick = () => {
    if (!SHEET_CTX) return;
    moveSession(SHEET_CTX.week, SHEET_CTX.sess, Number(b.dataset.moveto));
    closeSheet();
    render();
  });
  document.querySelectorAll("#sheetBody [data-slog]").forEach((inp) => inp.oninput = () => slogSet(inp.dataset.slog, inp.dataset.f, inp.value.trim()));
  wireExDemos();
  const sdStart = $("sdStart"); if (sdStart && SHEET_CTX && SHEET_CTX.sess) { const ss = SHEET_CTX.sess; sdStart.onclick = () => { closeSheet(); openStartWhereSheet(ss); }; }
  const sdAdd = $("sdAdd"); if (sdAdd) sdAdd.onclick = () => { const iso = sheetSessionIso(); closeSheet(); openAddSessionSheet(iso); };
}
function openSessionSheet(sess, week) {
  if (!sess) return;
  ensureSheet();
  SHEET_CTX = { sess, week: week || state.planWeek || 1 };
  $("sheetBody").innerHTML = sessionSheetHtml(sess, SHEET_CTX.week);
  wireSheet();
  $("sheetOv").classList.add("on");
}
function closeSheet() { stretchStop(); const o = $("sheetOv"); if (o) o.classList.remove("on"); WX_SHEET_OPEN = false; }
// Wire every element carrying data-open to open its session detail (keyed by stable session id).
function wireSessionTaps() {
  document.querySelectorAll("[data-open]").forEach((b) => b.onclick = () => {
    if (CAL_DRAGGED) { CAL_DRAGGED = false; return; } // that tap was a drag, not an open
    const wk = Number(b.dataset.oweek);
    openSessionSheet(rawSessionById(wk, b.dataset.oid), wk);
  });
}

// ---- Add-a-session: pick a runnable session from a list and put it on today's date ----------------
// A small library of the runnable session types in the current plan (one representative each), a
// per-date store of sessions the user has added, and the picker sheet + "Added today" card.
// Session types the user can add. Whatever their plan actually contains, plus the easy family —
// a beginner run-walk plan is built entirely from "easy" sessions, so without this the picker
// offered exactly one choice. The extras are cloned from the user's OWN base session, so a
// run-walk beginner gets a longer/shorter run-walk rather than a continuous run they can't yet do.
// Quality types (threshold, intervals, race pace) are deliberately NOT invented — if the plan
// hasn't introduced them yet, the runner isn't ready for them.
const ADD_ALWAYS = {
  recovery: { scale: 0.6, title: "Recovery run", desc: "Shorter and gentler than your usual easy session \\u2014 for the day after something hard." },
  easy: { scale: 1, title: "Easy run", desc: "Your everyday session at conversational effort." },
  long: { scale: 1.6, title: "Long run", desc: "A longer version of your easy session \\u2014 durability comes from time on your feet." },
};
function sessionLibrary() {
  const order = ["easy", "recovery", "long", "strides", "threshold", "vo2", "race-specific"];
  const byType = {};
  RAW.weeks.forEach((wk) => wk.sessions.forEach((s) => { if (PRIMARY_TYPES[s.type] && !byType[s.type]) byType[s.type] = s; }));
  const base = byType.easy || byType.long || byType.recovery;
  if (base) Object.keys(ADD_ALWAYS).forEach((t) => {
    if (byType[t]) return;
    const cfg = ADD_ALWAYS[t];
    const mins = Math.max(15, Math.round(base.estimatedDurationSeconds / 60 * cfg.scale / 5) * 5);
    byType[t] = Object.assign({}, base, {
      type: t, title: cfg.title, description: cfg.desc,
      estimatedDurationSeconds: mins * 60,
      estimatedDistanceMeters: base.estimatedDistanceMeters ? Math.round(base.estimatedDistanceMeters * cfg.scale) : undefined,
    });
  });
  return order.filter((t) => byType[t]).map((t) => byType[t]);
}
function extraRep(type) { return sessionLibrary().find((s) => s.type === type) || null; }
function loadExtra() { try { const a = JSON.parse(localStorage.getItem("interun_extra_v1") || "[]"); const t = todayIso(); return Array.isArray(a) ? a.filter((e) => e && e.date >= t) : []; } catch (e) { return []; } }
let EXTRA = loadExtra();
let EXTRA_SEQ = 0;
function saveExtra() { try { localStorage.setItem("interun_extra_v1", JSON.stringify(EXTRA)); } catch (e) {} }
// Sessions are added to the day you're LOOKING AT, not blindly to today: the selected day on Today,
// or the day of the session whose sheet you opened (which may be weeks away, on Plan or the calendar).
let ADD_TARGET = null;
