function wireWhyView() { wireWhyInputs(() => { if (state.tab === "support" && state.support === "why") render(); }); }
// ---- Connected apps & devices -------------------------------------------------------------------
// The honest version of the screen every big fitness app has. Three kinds of row: things that are
