  LIVE.win.push({ t: at, d: LIVE.dist });
  while (LIVE.win.length > 1 && at - LIVE.win[0].t > 12000) LIVE.win.shift();
  let cur = currentGpsPace(at); if (cur && cur > 1200) cur = null; // slower than 20:00/km ⇒ stopped
