  const stats = [
    { icon: 0, label: "DISTANCE", val: dParts[0], unit: (dParts[1] || "km").toUpperCase() },
    { icon: 1, label: "DURATION", val: run.time || "0:00", unit: "MIN" },
    { icon: 2, label: "AVG PACE", val: pParts[0], unit: (pParts[1] || "/km").toUpperCase() },
  ];
