    g.strokeStyle = "rgba(61,255,176,.3)"; g.lineWidth = 1.5; g.beginPath(); g.moveTo(sxp + 30, sy + 84); g.lineTo(sxp + sw - 30, sy + 84); g.stroke();
    g.fillStyle = "#fff"; g.font = "800 72px " + FF; g.fillText(st.val, sxp + 32, sy + 170);
