  $("guideSkip").style.visibility = GUIDE.i >= GUIDE.steps.length - 1 ? "hidden" : "visible";
  $("guideDots").innerHTML = GUIDE.steps.map((_, i) => '<span class="gd' + (i === GUIDE.i ? " on" : "") + '"></span>').join("");
